   MdBlock::BlockQuote{blocks}=>{out.insert_key("md_block_quote",id,&[])?;out.push_frontier(&mut frames,WriteFrame::Blocks(blocks,0,BlockOwner::Quote(id)))?;},
   MdBlock::ThematicBreak=>{out.insert_key("md_thematic_break",id,&[])?;},
