  WriteFrame::Items(items,index,list)=>{let Some(blocks)=items.get(index)else{continue};out.push_frontier(&mut frames,WriteFrame::Items(items,index+1,list))?;let id=out.insert("md_list_item",&[Cell::Integer(list),Cell::Integer(ordinal(index)?)])?;out.push_frontier(&mut frames,WriteFrame::Blocks(blocks,0,BlockOwner::Item(id)))?;},
