fn relationships(database:&SqliteDatabase,table:&str,parents:&Entities<'_>,targets:Option<&Entities<'_>>,owned:&mut BTreeSet<i64>,control:&mut SqliteSnapshotControl<'_>)->Result<Children,ValueError>{
